screen.applet:
from Tools.Directories import resolveFilename, fileExists, SCOPE_CURRENT_SKIN
from Tools.LoadPixmap import LoadPixmap
from skin import menuicons
iconSize = 96
if not hasattr(self, "gridIcons"):
    self.gridIcons = {}
icons = self.gridIcons
menuSource = self["menu"]
rows = []
changed = False
for item in menuSource.list:
    item = tuple(item)
    key = item[2] if len(item) > 2 else None
    if key is not None:
        icon = icons.get(key)
        if icon is None:
            path = menuicons.get(key, menuicons.get("default", ""))
            if path:
                icon = LoadPixmap(resolveFilename(SCOPE_CURRENT_SKIN, path), cached=True, width=iconSize, height=iconSize, scaletoFit=1)
                icons[key] = icon
        if icon is not None and (len(item) < 6 or item[5] is not icon):
            item = (item + (None,) * 5)[:5] + (icon,) + item[6:]
            changed = True
    rows.append(item)
if changed:
    menuSource.updateList(rows)
if not hasattr(self, "gridSelected"):
    self.gridSelected = [0]
selected = self.gridSelected
gridList = next((renderer for renderer in self.renderer if renderer.__class__.__name__ == "COCGridListbox" and renderer.content is not None), None)
if gridList is not None:
    selected[0] = gridList.index or 0
    if not hasattr(self, "gridSelectedBuild"):
        selectedIcons = {}
        def selectedTile(*item, menuSource=menuSource, selected=selected, selectedIcons=selectedIcons, menuicons=menuicons, resolveFilename=resolveFilename,
                         skinScope=SCOPE_CURRENT_SKIN, fileExists=fileExists, LoadPixmap=LoadPixmap, iconSize=iconSize):
            if len(item) >= 6 and item[5]:
                rows = menuSource.list
                index = selected[0]
                if 0 <= index < len(rows) and rows[index][2] == item[2] and rows[index][0] == item[0]:
                    key = item[2]
                    if key not in selectedIcons:
                        icon = None
                        path = menuicons.get(key, menuicons.get("default", ""))
                        if path.endswith(".svg"):
                            path = resolveFilename(skinScope, path[:-4] + "_selected.svg")
                            if fileExists(path):
                                icon = LoadPixmap(path, cached=True, width=iconSize, height=iconSize, scaletoFit=1)
                        selectedIcons[key] = icon
                    if selectedIcons[key]:
                        item = item[:5] + (selectedIcons[key],) + item[6:]
            return item
        def selectionMoved(selected=selected, gridList=gridList):
            selected[0] = gridList.index or 0
        gridList.content.setBuildFunc(selectedTile)
        menuSource.onSelectionChanged.append(selectionMoved)
        self.gridSelectedBuild = True

