screen.applet:
from Tools.Directories import resolveFilename, fileExists, SCOPE_CURRENT_SKIN
from Tools.LoadPixmap import LoadPixmap
from skin import menuicons
iconSize = 96
if not hasattr(self, "gridIcons"):
    self.gridIcons = {}
if not hasattr(self, "gridStates"):
    self.gridStates = {}
icons = self.gridIcons
def sourceOf(renderer):
    # the source of the renderer is its converter, the list is the source behind it
    source = renderer.source
    while source is not None and not hasattr(source, "list"):
        source = getattr(source, "source", None)
    return source
for name in ("bouquets", "menu"):
    if name not in self:
        continue
    menuSource = self[name]
    rows = []
    changed = False
    for item in menuSource.list:
        item = tuple(item)
        key = item[2] if len(item) > 2 else None
        if key is not None:
            icon = icons.get(key)
            if icon is None:
                path = menuicons.get(key, menuicons.get("default", ""))
                if path:
                    icon = LoadPixmap(resolveFilename(SCOPE_CURRENT_SKIN, path), cached=True, width=iconSize, height=iconSize, scaletoFit=1)
                    icons[key] = icon
            if icon is not None and (len(item) < 6 or item[5] is not icon):
                item = (item + (None,) * 5)[:5] + (icon,) + item[6:]
                changed = True
        rows.append(item)
    if changed:
        menuSource.updateList(rows)
    # (a loop, not a generator: the applet runs with its names as locals, which a generator expression does not see)
    gridList = None
    for renderer in self.renderer:
        if renderer.__class__.__name__ == "COCGridListbox" and renderer.content is not None and sourceOf(renderer) is menuSource:
            gridList = renderer
            break
    if gridList is None:
        continue
    state = self.gridStates.setdefault(name, {"selected": [0], "built": False})
    selected = state["selected"]
    selected[0] = gridList.index or 0
    if not state["built"]:
        selectedIcons = {}
        def selectedTile(*item, menuSource=menuSource, selected=selected, selectedIcons=selectedIcons, gridList=gridList, menuicons=menuicons,
                         resolveFilename=resolveFilename, skinScope=SCOPE_CURRENT_SKIN, fileExists=fileExists, LoadPixmap=LoadPixmap, iconSize=iconSize):
            if len(item) >= 6 and item[5] and gridList.selection_enabled:
                rows = menuSource.list
                index = selected[0]
                if 0 <= index < len(rows) and rows[index][2] == item[2] and rows[index][0] == item[0]:
                    key = item[2]
                    if key not in selectedIcons:
                        icon = None
                        path = menuicons.get(key, menuicons.get("default", ""))
                        if path.endswith(".svg"):
                            path = resolveFilename(skinScope, path[:-4] + "_selected.svg")
                            if fileExists(path):
                                icon = LoadPixmap(path, cached=True, width=iconSize, height=iconSize, scaletoFit=1)
                        selectedIcons[key] = icon
                    if selectedIcons[key]:
                        item = item[:5] + (selectedIcons[key],) + item[6:]
            return item
        def selectionMoved(selected=selected, gridList=gridList):
            selected[0] = gridList.index or 0
        gridList.content.setBuildFunc(selectedTile)
        menuSource.onSelectionChanged.append(selectionMoved)
        state["built"] = True

